import React, { useCallback, useRef } from 'react';
import { useKeyboardShortcuts } from '@fiverr-private/hooks';
import { TimesButton } from '@fiverr-private/button';
import { useDrawerContext } from '../DrawerContext';
import { DrawerCloseButtonProps } from '../types';
import { DRAWER_CLOSE_BTN_ID } from '../constants';

const DrawerCloseButton = ({
  onClick,
  dataTrackTag = 'drawer_close_button',
  dataTrackValue,
}: DrawerCloseButtonProps) => {
  const { close } = useDrawerContext();
  const ref = useRef(null);
  const getTarget = useCallback(() => ref.current, [ref]);

  const onTrigger = () => {
    onClick?.();
    close();
  };

  useKeyboardShortcuts(
    [
      {
        trigger: 'enter',
        handler: onTrigger,
      },
      {
        trigger: 'space',
        handler: onTrigger,
      },
    ],
    getTarget
  );

  return (
    <TimesButton ref={ref} size="md" dataTrackTag={dataTrackTag} dataTrackValue={dataTrackValue} onClick={onTrigger} />
  );
};

DrawerCloseButton.displayName = 'DrawerCloseButton';

Object.assign(DrawerCloseButton, {
  id: DRAWER_CLOSE_BTN_ID,
});

export default DrawerCloseButton;
