import React from 'react';
import { useDrawerContext } from '../DrawerContext';
import { DrawerTriggerProps } from '../types';

const DrawerTrigger = ({
  children,
  as: Element = 'span',
  dataTestId,
  dataTrackTag = 'drawer_trigger',
  dataTrackValue,
}: DrawerTriggerProps) => {
  const { open } = useDrawerContext();

  return (
    <Element onClick={open} data-testid={dataTestId} data-track-tag={dataTrackTag} data-track-value={dataTrackValue}>
      {children}
    </Element>
  );
};

DrawerTrigger.displayName = 'DrawerTrigger';

export default DrawerTrigger;
