import React, { forwardRef } from 'react';
import { excludeChildrenByType, findChildByType } from '@fiverr-private/ui_utils';
import { Stack } from '@fiverr-private/layout_components';
import { Heading } from '@fiverr-private/typography';
import type { Types } from '@fiverr-private/theme';
import { DrawerChildrenProps } from '../types';
import { DRAWER_CLOSE_BTN_ID } from '../constants';
import { DEFAULT_PADDING_BOTTOM, DEFAULT_PADDING_TOP, DEFAULT_PADDING_X } from './constants';

interface DrawerHeaderProps
  extends DrawerChildrenProps,
    Types.GlobalStylingProps,
    Pick<Types.ContainerProps, 'paddingX' | 'paddingTop' | 'paddingBottom'>,
    Pick<Types.BoxType, 'dataTrackTag' | 'dataTrackValue'> {}

const DrawerHeader = forwardRef<HTMLElement, DrawerHeaderProps>(
  (
    {
      children,
      paddingX = DEFAULT_PADDING_X,
      paddingTop = DEFAULT_PADDING_TOP,
      paddingBottom = DEFAULT_PADDING_BOTTOM,
      dataTrackTag = 'drawer_header',
      ...restProps
    },
    ref
  ) => {
    const closeButton = findChildByType(children, DRAWER_CLOSE_BTN_ID);
    const restOfChildren = excludeChildrenByType(children, DRAWER_CLOSE_BTN_ID);

    return (
      <Stack
        as="header"
        alignItems="center"
        justifyContent="spaceBetween"
        borderBottomWidth="sm"
        borderStyle="solid"
        borderColor="border"
        paddingX={paddingX}
        paddingTop={paddingTop}
        paddingBottom={paddingBottom}
        ref={ref}
        dataTrackTag={dataTrackTag}
        {...restProps}
      >
        <Heading as="h4" flex="1">
          {restOfChildren}
        </Heading>
        {closeButton}
      </Stack>
    );
  }
);

DrawerHeader.displayName = 'DrawerHeader';

export default DrawerHeader;
